program.compute:
options = read('/input/options')
existing = read('/output/selection')
if valid(existing):
    result = existing
else:
    result = []
    for k in range(goal['min_count'], goal['max_count'] + 1):
        for group in combinations(options, k):
            ids = [item['id'] for item in group]
            if valid(ids):
                result = ids
                break
        if result:
            break

program.effects:
if not exists('/output/selection'):
    write('/output/selection', result)
if receipt('report') == 'unattempted':
    send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')

